# Implementation
def summarize_sessions(events: list[dict], *, active_window: int) -> dict:
    """Summarize session activity without mutating the input event list.

    Each event has keys: session_id, ts, kind.
    Supported kinds: open, message, close.

    Output format:
    {
        "active_sessions": [sorted session ids whose latest event is within active_window of max ts and not closed],
        "closed_sessions": [sorted session ids that were explicitly closed],
        "message_counts": {session_id: count_of_message_events},
        "timeline": ["<ts>:<session_id>:<kind>", ... in original order],
    }

    Rules:
    - A message before open is invalid.
    - Opening an already-open session is invalid.
    - Closing a missing or already-closed session is invalid.
    - Unsupported kinds are invalid.
    """
    if active_window < 0:
        raise ValueError("active_window must be non-negative")

    open_sessions = {}
    closed_sessions = set()
    message_counts = {}
    timeline = []
    max_ts = None

    for event in events:
        session_id = event["session_id"]
        ts = event["ts"]
        kind = event["kind"]
        timeline.append(f"{ts}:{session_id}:{kind}")
        max_ts = ts if max_ts is None else max(max_ts, ts)

        if kind == "open":
            if session_id in open_sessions:
                raise ValueError("session already open")
            open_sessions[session_id] = ts
            message_counts.setdefault(session_id, 0)
            closed_sessions.discard(session_id)
        elif kind == "message":
            if session_id not in open_sessions:
                raise ValueError("message for inactive session")
            message_counts[session_id] = message_counts.get(session_id, 0) + 1
            open_sessions[session_id] = ts
        elif kind == "close":
            if session_id not in open_sessions:
                raise ValueError("close for inactive session")
            del open_sessions[session_id]
            closed_sessions.add(session_id)
            message_counts.setdefault(session_id, 0)
        else:
            raise ValueError("unsupported event kind")

    if max_ts is None:
        active = []
    else:
        active = sorted(
            session_id
            for session_id, last_seen in open_sessions.items()
            if max_ts - last_seen <= active_window
        )

    return {
        "active_sessions": active,
        "closed_sessions": sorted(closed_sessions),
        "message_counts": dict(sorted(message_counts.items())),
        "timeline": timeline,
    }

# Solution
def measurement_mapping(bitstring: str) -> dict[str, int]:
    """Map q0/q1 to integer measurement results from a two-bit string.

    Input ordering is q1q0, so the rightmost bit is q0.
    """
    if len(bitstring) != 2 or any(ch not in "01" for ch in bitstring):
        raise ValueError("expected a two-bit measurement string")
    return {"q0": int(bitstring[1]), "q1": int(bitstring[0])}

# Solution
def _normalize_pauli(label: str) -> str:
    normalized = label.strip().upper()
    if normalized not in {"I", "X", "Y", "Z"}:
        raise ValueError(f"unsupported Pauli operator: {label!r}")
    return normalized


_CONJUGATION_RULES = {
    "H": {
        "I": (1, "I"),
        "X": (1, "Z"),
        "Y": (-1, "Y"),
        "Z": (1, "X"),
    },
    "S": {
        "I": (1, "I"),
        "X": (1, "Y"),
        "Y": (-1, "X"),
        "Z": (1, "Z"),
    },
    "SDG": {
        "I": (1, "I"),
        "X": (-1, "Y"),
        "Y": (1, "X"),
        "Z": (1, "Z"),
    },
}


def apply_gate_sequence(pauli: str, gates: list[str]) -> tuple[int, str]:
    """Update a signed single-qubit Pauli under Clifford conjugation."""
    raw = pauli.strip()
    sign = -1 if raw.startswith("-") else 1
    label = raw[1:] if raw.startswith("-") else raw
    label = _normalize_pauli(label)

    for gate in gates:
        gate_name = gate.strip().upper()
        if gate_name not in _CONJUGATION_RULES:
            raise ValueError(f"unsupported gate: {gate!r}")
        gate_sign, next_label = _CONJUGATION_RULES[gate_name][label]
        sign *= gate_sign
        label = next_label

    return sign, label

# Solution
def apply_events(events):
    state = {"active": {}, "history": []}

    for event in events:
        kind = event["type"]
        session_id = event["session_id"]

        if kind == "start":
            if session_id in state["active"]:
                raise ValueError(f"session already active: {session_id}")
            state["active"][session_id] = {
                "user": event["user"],
                "started_at": event["ts"],
                "last_seen": event["ts"],
                "messages": 0,
            }
            continue

        if session_id not in state["active"]:
            raise ValueError(f"session not active: {session_id}")

        if kind == "message":
            active = state["active"][session_id]
            active["messages"] += 1
            active["last_seen"] = event["ts"]
            continue

        if kind == "end":
            active = state["active"].pop(session_id)
            state["history"].append(
                {
                    "session_id": session_id,
                    "user": active["user"],
                    "started_at": active["started_at"],
                    "ended_at": event["ts"],
                    "messages": active["messages"],
                }
            )
            continue

        raise ValueError(f"unknown event type: {kind}")

    state["history"].sort(key=lambda item: (item["started_at"], item["session_id"]))
    return state

